//! The pin manifest `pins/stable.toml` (ARCHITECTURE §14.7; core §10.2) [D 87]: the Xcode compatibility rows and
//! the pinned, verified download of every managed component. It is generated by `cargo xtask pins` from upstream
//! release metadata (never hand-typed URLs or digests), signed with minisign, and embedded in the binary.
//!
//! Debug builds trust the development key (`pins/dev-minisign.pub`, secret half outside the repository); release
//! builds trust only the release keys W26 adds to [`RELEASE_KEYS`].

use std::collections::BTreeMap;

use russet_core::error::{Error, Result, codes};
use serde::{Deserialize, Serialize};

use crate::version::Version;

/// The embedded manifest (generated; see `xtask/src/pins.rs`).
pub const EMBEDDED_MANIFEST: &str = include_str!("../../../pins/stable.toml");
/// Its minisign signature.
pub const EMBEDDED_SIGNATURE: &str = include_str!("../../../pins/stable.toml.minisig");
/// The development public key; trusted by debug builds only [D 87].
pub const DEV_PUBLIC_KEY: &str = include_str!("../../../pins/dev-minisign.pub");
/// Release public keys (W26). Empty until the release key exists, so release builds trust no manifest yet.
pub const RELEASE_KEYS: &[&str] = &[];

/// The keys this build trusts.
pub fn trusted_keys() -> Vec<&'static str> {
    if cfg!(debug_assertions) { vec![DEV_PUBLIC_KEY] } else { RELEASE_KEYS.to_vec() }
}

/// One `[[xcode]]` row: which Swift and linker an Xcode SDK needs.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case", deny_unknown_fields)]
pub struct XcodeCompat {
    pub version: String,
    pub build: String,
    pub ios_sdk: String,
    /// The Swift `major.minor` the SDK needs ("this SDK is not supported by the compiler" otherwise).
    pub swift: String,
    /// The oldest LLD that reads the SDK's `arm64e.x1` TBDs.
    pub min_lld: String,
    /// The oldest darwin-tools release that does (its LLD is patched).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub min_darwin_tools: Option<String>,
}

/// One downloadable artifact.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case", deny_unknown_fields)]
pub struct Artifact {
    pub url: String,
    pub size: u64,
    /// Lowercase hex SHA-256 of the downloaded file.
    pub sha256: String,
    /// `tar.gz`, `tar.zst`, …
    pub format: String,
}

/// One `[[component]]`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case", deny_unknown_fields)]
pub struct ComponentPin {
    /// `python-shared`, `darwin-tools`, …
    pub name: String,
    pub version: String,
    /// Where the metadata came from, for example `python-build-standalone` or `github:owner/repo@tag`.
    pub source: String,
    /// The upstream release (PBS's `20261009`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub release: Option<String>,
    /// Platform key (`linux-x86_64`, `linux-aarch64`, …) → artifact.
    pub artifacts: BTreeMap<String, Artifact>,
}

/// The manifest.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case", deny_unknown_fields)]
pub struct PinManifest {
    pub schema: u32,
    /// The manifest id, for example `2026.10.11`.
    pub id: String,
    pub min_russet: String,
    /// When `cargo xtask pins` generated it (RFC 3339).
    pub generated_at: String,
    #[serde(default)]
    pub xcode: Vec<XcodeCompat>,
    #[serde(default)]
    pub component: Vec<ComponentPin>,
}

fn pins_invalid(msg: impl Into<String>) -> Error {
    Error::new(codes::toolchain::PINS_INVALID, msg).with_hint(
        "The pin manifest must be generated by `cargo xtask pins` and signed with a trusted key; reinstall Russet \
         or run `russet toolchain pins update`.",
    )
}

impl PinManifest {
    /// Parses and verifies `toml` against its minisign signature and one of `keys` (public-key file contents).
    pub fn load_verified(toml: &str, minisig: &str, keys: &[&str]) -> Result<Self> {
        let sig = minisign_verify::Signature::decode(minisig)
            .map_err(|e| pins_invalid(format!("the pin manifest signature is unreadable: {e}")))?;
        let mut last = None;
        let verified = keys.iter().any(|k| {
            let res = minisign_verify::PublicKey::decode(k.trim())
                .or_else(|_| minisign_verify::PublicKey::from_base64(k.trim()))
                .and_then(|pk| pk.verify(toml.as_bytes(), &sig, false));
            let ok = res.is_ok();
            last = res.err();
            ok
        });
        if !verified {
            let why = last.map_or_else(|| "no trusted key".to_owned(), |e| e.to_string());
            return Err(pins_invalid(format!("the pin manifest signature does not verify: {why}")));
        }
        Self::parse(toml)
    }

    /// Parses a manifest without checking its signature (generators and tests only).
    pub fn parse(toml: &str) -> Result<Self> {
        let m: PinManifest =
            toml::from_str(toml).map_err(|e| pins_invalid(format!("the pin manifest is invalid: {}", e.message())))?;
        if m.schema != 1 {
            return Err(pins_invalid(format!("unsupported pin manifest schema {}", m.schema)));
        }
        for c in &m.component {
            for (platform, a) in &c.artifacts {
                if a.sha256.len() != 64 || !a.sha256.bytes().all(|b| b.is_ascii_hexdigit() && !b.is_ascii_uppercase()) {
                    return Err(pins_invalid(format!("{} {platform}: sha256 is not 64 lowercase hex digits", c.name)));
                }
                let allowed = reqwest::Url::parse(&a.url).is_ok_and(|u| {
                    u.scheme() == "https" || (u.scheme() == "http" && u.host_str() == Some("127.0.0.1"))
                });
                if !allowed {
                    return Err(pins_invalid(format!("{} {platform}: only https URLs are allowed", c.name)));
                }
            }
        }
        Ok(m)
    }

    /// A manifest with no rows and no components (nothing verified).
    pub fn empty() -> Self {
        Self {
            schema: 1,
            id: "none".into(),
            min_russet: "0.1.0".into(),
            generated_at: String::new(),
            xcode: Vec::new(),
            component: Vec::new(),
        }
    }

    /// The embedded manifest, verified with this build's trusted keys.
    pub fn embedded() -> Result<Self> {
        Self::load_verified(EMBEDDED_MANIFEST, EMBEDDED_SIGNATURE, &trusted_keys())
    }

    /// The compatibility row of an Xcode version (`27.0`) or build (`27A266a`).
    pub fn xcode(&self, version_or_build: &str) -> Option<&XcodeCompat> {
        self.xcode.iter().find(|x| x.build == version_or_build).or_else(|| {
            let want: Version = version_or_build.parse().ok()?;
            self.xcode.iter().find(|x| x.version.parse::<Version>().is_ok_and(|v| v == want))
        })
    }

    /// The pinned `version` of component `name` (`None` = the only or newest one).
    pub fn component(&self, name: &str, version: Option<&str>) -> Option<&ComponentPin> {
        let mut matching: Vec<&ComponentPin> = self
            .component
            .iter()
            .filter(|c| c.name == name)
            .filter(|c| version.is_none_or(|v| c.version == v || v == "latest" || v.is_empty()))
            .collect();
        matching.sort_by(|a, b| {
            let va = a.version.parse::<Version>().ok();
            let vb = b.version.parse::<Version>().ok();
            vb.cmp(&va)
        });
        matching.first().copied()
    }
}

/// The platform key of this host: `linux-x86_64`, `linux-aarch64`, `windows-x86_64`, `windows-aarch64`, …
pub fn host_platform() -> String {
    format!("{}-{}", std::env::consts::OS, std::env::consts::ARCH)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_embedded_manifest_verifies_with_the_dev_key() {
        let m = PinManifest::embedded().expect("embedded pins verify in debug builds");
        assert_eq!(m.schema, 1);
        let py = m.component("python-shared", None).expect("python-shared pinned");
        assert_eq!(py.version, "3.12.15");
        assert_eq!(py.release.as_deref(), Some("20261009"));
        assert!(py.artifacts.contains_key("linux-x86_64"));
        let dt = m.component("darwin-tools", Some("1.1.0")).expect("darwin-tools pinned");
        assert!(dt.artifacts["linux-x86_64"].url.ends_with("/v1.1.0/toolset-x86_64.tar.gz"));
        let x = m.xcode("27.0").expect("Xcode 27 row");
        assert_eq!((x.build.as_str(), x.swift.as_str(), x.min_lld.as_str()), ("27A266a", "6.4", "23.1.3"));
        assert_eq!(m.xcode("27A266a").map(|r| r.version.as_str()), Some("27.0"));
    }

    #[test]
    fn an_altered_manifest_or_signature_is_rejected() {
        let altered = EMBEDDED_MANIFEST.replacen("3.12.15", "3.12.16", 1);
        let err = PinManifest::load_verified(&altered, EMBEDDED_SIGNATURE, &[DEV_PUBLIC_KEY]).expect_err("altered");
        assert_eq!(err.code(), codes::toolchain::PINS_INVALID);
        let err = PinManifest::load_verified(EMBEDDED_MANIFEST, "garbage", &[DEV_PUBLIC_KEY]).expect_err("sig");
        assert_eq!(err.code(), codes::toolchain::PINS_INVALID);
        let err = PinManifest::load_verified(EMBEDDED_MANIFEST, EMBEDDED_SIGNATURE, &[]).expect_err("no key");
        assert_eq!(err.code(), codes::toolchain::PINS_INVALID);
    }
}
